4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The single definition of a truncated SHA-256 fingerprint: the leading upper-case hex
9	 * characters of the digest of a string. Shared by everything that fingerprints owner data
10	 * (customer code hash, household id) so they hash identically.
11	 */
12	public final class Sha256 {
13	
14	    private Sha256() {
15	    }
16	
17	    /**
18	     * The first {@code length} upper-case hex characters of SHA-256 over the UTF-8 bytes of
19	     * {@code value}.
20	     *
21	     * @param value  the string to hash
22	     * @param length the number of leading hex characters to return
23	     * @return the truncated upper-case hex digest
24	     */
25	    public static String upperHex(String value, int length) {
26	        try {
27	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder hex = new StringBuilder(digest.length * 2);
29	            for (byte b : digest) {
30	                hex.append(String.format("%02X", b & 0xFF));
31	            }
32	            return hex.substring(0, length);
33	        } catch (NoSuchAlgorithmException ex) {
34	            throw new IllegalStateException("SHA-256 is required to derive a fingerprint", ex);
35	        }
36	    }
37	}
