1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * Flags a soft duplicate: a create that shares an existing owner's last name and postcode
13	 * while carrying a <em>different</em> telephone. The owner is still created; the response
14	 * merely carries {@code possibleDuplicate}/{@code possibleDuplicateOf} pointing at the matched
15	 * owner.
16	 *
17	 * <p>A declared household member — one created with {@code sharesHousehold} — deliberately
18	 * shares an existing owner's last name and postcode, so it is <em>not</em> a suspected
19	 * duplicate and is left unflagged.
20	 *
21	 * <p>Runs after {@link BuildOwner} but before the owner is saved, so it compares against the
22	 * owners that existed before this create (and so never matches the owner being built), and
23	 * mutates the built {@link Owner} in place. When several owners match, the one with the lowest
24	 * id is reported, so the result is deterministic. Last names are compared case-insensitively
25	 * (as elsewhere, e.g. {@link AssignOwnerNamesakeCount}); postcode and telephone are compared in
26	 * their stored, normalized form.
27	 */
28	public class AssignOwnerPossibleDuplicate {
29	
30	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return; // a declared household member is not a suspected duplicate
33	        }
34	        String lastName = canonical(owner.getLastName());
35	        String postcode = trimmed(owner.getPostcode());
36	        String telephone = trimmed(owner.getTelephone());
37	        if (postcode == null) {
38	            return; // no postcode to share, so no soft match
39	        }
40	        Owner match = null;
41	        for (Owner existing : Owners.active(ownerRepository.findAll())) {
42	            if (lastName.equals(canonical(existing.getLastName()))
43	                    && postcode.equals(trimmed(existing.getPostcode()))
44	                    && !Objects.equals(telephone, trimmed(existing.getTelephone()))
45	                    && (match == null || existing.getId() < match.getId())) {
46	                match = existing;
47	            }
48	        }
49	        if (match != null) {
50	            owner.setPossibleDuplicateOf(match.getId());
51	        }
52	    }
53	
54	    private static String canonical(String value) {
55	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
56	    }
57	
58	    private static String trimmed(String value) {
59	        if (value == null) {
60	            return null;
61	        }
62	        String trimmed = value.trim();
63	        return trimmed.isEmpty() ? null : trimmed;
64	    }
65	}
