1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Locale;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.model.Sha256;
9	
10	/**
11	 * The single definition of what a "household" is: owners sharing the same last name and
12	 * postcode, compared case-insensitively with runs of whitespace collapsed to a single
13	 * space. The {@code householdId} is derived deterministically from those two fields, so
14	 * every owner with the same last name and postcode computes the same id automatically,
15	 * regardless of creation order.
16	 *
17	 * <p>Shared by {@link AssignOwnerHousehold} (which stamps the id),
18	 * {@link AssignOwnerHouseholdSize} (which counts members) and
19	 * {@link AssignOwnerMembershipLevelCap} (which caps a new member's level), so all decide
20	 * membership identically.
21	 */
22	final class OwnerHouseholds {
23	
24	    private static final int ID_HEX_LENGTH = 12;
25	
26	    private OwnerHouseholds() {
27	    }
28	
29	    /**
30	     * A stable identifier for the household of an owner with this {@code lastName} and
31	     * {@code postcode}: the first {@value #ID_HEX_LENGTH} hex characters of SHA-256 over
32	     * {@code normalizedLastName + '|' + postcode}. Every member computes the same value, so
33	     * it is deterministic and independent of creation order.
34	     */
35	    static String householdId(String lastName, String postcode) {
36	        String key = canonical(lastName) + "|" + trimmed(postcode);
37	        return Sha256.upperHex(key, ID_HEX_LENGTH);
38	    }
39	
40	    /**
41	     * The existing owners that belong to the household identified by {@code lastName} and
42	     * {@code postcode} — those whose own last name and postcode hash to the same
43	     * {@link #householdId}.
44	     */
45	    static List<Owner> members(Iterable<Owner> owners, String lastName, String postcode) {
46	        String householdId = householdId(lastName, postcode);
47	        List<Owner> members = new ArrayList<>();
48	        for (Owner existing : owners) {
49	            if (householdId.equals(householdId(existing.getLastName(), existing.getPostcode()))) {
50	                members.add(existing);
51	            }
52	        }
53	        return members;
54	    }
55	
56	    /** Trim, collapse internal whitespace to a single space, and lower-case for comparison. */
57	    private static String canonical(String value) {
58	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
59	    }
60	
61	    /** The trimmed value, or the empty string when absent. */
62	    private static String trimmed(String value) {
63	        return value == null ? "" : value.trim();
64	    }
65	}
