1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
7	
8	/**
9	 * The single normalization rule for owner telephones: convert a raw telephone to E.164
10	 * form. Spaces, dashes and brackets are stripped; a leading {@code +} with its country
11	 * code is kept, otherwise country code {@code +61} is assumed and a single leading
12	 * {@code 0} is dropped from the national digits. The result must carry 8 to 15 digits
13	 * after the {@code +}, and — for a recognised country code — exactly the national-number
14	 * length that country requires ({@code +61} → 9 national digits, {@code +1} → 10). Shared
15	 * by {@link NormalizeOwnerTelephone} (which stores the E.164 value on the request) so
16	 * every telephone is stored and compared the same way, and by the owner mapper's
17	 * {@link #toDisplay} for the human-readable {@code telephoneDisplay}.
18	 */
19	public final class OwnerTelephones {
20	
21	    private static final String DEFAULT_COUNTRY_CODE = "61";
22	    private static final int MIN_DIGITS = 8;
23	    private static final int MAX_DIGITS = 15;
24	
25	    /**
26	     * Country calling code → required national-number length. Ordered longest code first
27	     * so {@link #nationalLength} matches the most specific calling code (e.g. {@code 61}
28	     * before {@code 1}).
29	     */
30	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
31	
32	    static {
33	        NATIONAL_LENGTHS.put("61", 9);
34	        NATIONAL_LENGTHS.put("1", 10);
35	    }
36	
37	    private OwnerTelephones() {
38	    }
39	
40	    /**
41	     * The E.164 form of {@code telephone} (a leading {@code +} followed by 8 to 15 digits).
42	     *
43	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
44	     */
45	    static String toE164(String telephone) throws InvalidTelephoneException {
46	        String cleaned = (telephone == null ? "" : telephone).replaceAll("[\\s()-]", "");
47	
48	        String digits;
49	        if (cleaned.startsWith("+")) {
50	            digits = cleaned.substring(1);
51	        } else {
52	            digits = dropSingleLeadingZero(cleaned);
53	            digits = DEFAULT_COUNTRY_CODE + digits;
54	        }
55	
56	        if (!digits.matches("\\d+") || digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
57	            throw new InvalidTelephoneException(
58	                    "Telephone must form a valid E.164 number with " + MIN_DIGITS + " to " + MAX_DIGITS
59	                            + " digits after the country code");
60	        }
61	        requireCountryNationalLength(digits);
62	        return "+" + digits;
63	    }
64	
65	    /**
66	     * The human-readable form of a stored E.164 {@code telephone}: the {@code +} country code,
67	     * a space, then the national digits grouped in threes (e.g. {@code +61412345678} →
68	     * {@code +61 412 345 678}). The country code is split off using the same recognised calling
69	     * codes as {@link #toE164}; an unrecognised number is grouped without a country-code split.
70	     */
71	    public static String toDisplay(String e164) {
72	        String digits = e164.startsWith("+") ? e164.substring(1) : e164;
73	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
74	            String code = country.getKey();
75	            if (digits.startsWith(code) && digits.length() - code.length() == country.getValue()) {
76	                return "+" + code + " " + groupInThrees(digits.substring(code.length()));
77	            }
78	        }
79	        return "+" + groupInThrees(digits);
80	    }
81	
82	    /** The digits split into space-separated groups of three, left to right. */
83	    private static String groupInThrees(String digits) {
84	        StringBuilder grouped = new StringBuilder();
85	        for (int i = 0; i < digits.length(); i++) {
86	            if (i > 0 && i % 3 == 0) {
87	                grouped.append(' ');
88	            }
89	            grouped.append(digits.charAt(i));
90	        }
91	        return grouped.toString();
92	    }
93	
94	    /**
95	     * For a recognised country calling code, rejects a number whose national part is not the
96	     * exact length that country requires. Unrecognised codes keep the generic length check only.
97	     */
98	    private static void requireCountryNationalLength(String digits) throws InvalidTelephoneException {
99	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
100	            String code = country.getKey();
101	            if (digits.startsWith(code)) {
102	                int nationalLength = digits.length() - code.length();
103	                int required = country.getValue();
104	                if (nationalLength != required) {
105	                    throw new InvalidTelephoneException("Telephone with country code +" + code
106	                            + " must have " + required + " national digits, but has " + nationalLength);
107	                }
108	                return;
109	            }
110	        }
111	    }
112	
113	    private static String dropSingleLeadingZero(String digits) {
114	        return digits.startsWith("0") ? digits.substring(1) : digits;
115	    }
116	}
117

