1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	/**
8	 * The single rule set for owner email addresses: what counts as "present", what counts as
9	 * a syntactically valid address, which domains are disposable, and how one is normalized for
10	 * storage. Shared so every step that touches an owner email treats it the same way.
11	 */
12	final class OwnerEmails {
13	
14	    /** local-part {@code @} domain, no whitespace, and a dotted domain. */
15	    private static final Pattern SYNTAX = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
16	
17	    /** Domains of disposable/throwaway email providers that owners may not use. */
18	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
19	            "mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    private OwnerEmails() {
22	    }
23	
24	    /** An email is present when it is non-null and not blank; blank is treated as omitted. */
25	    static boolean isPresent(String email) {
26	        return email != null && !email.isBlank();
27	    }
28	
29	    /** Whether {@code email} is a syntactically valid address. */
30	    static boolean isValid(String email) {
31	        return email != null && SYNTAX.matcher(email).matches();
32	    }
33	
34	    /** The stored form of an email: trimmed and lower-cased. */
35	    static String normalize(String email) {
36	        return email.trim().toLowerCase(Locale.ROOT);
37	    }
38	
39	    /** The domain part (after the {@code @}) of {@code email}, lower-cased, or {@code null}
40	     *  when the address has no domain. */
41	    static String domainOf(String email) {
42	        if (email == null) {
43	            return null;
44	        }
45	        int at = email.lastIndexOf('@');
46	        if (at < 0 || at == email.length() - 1) {
47	            return null;
48	        }
49	        return email.substring(at + 1).toLowerCase(Locale.ROOT);
50	    }
51	
52	    /** Whether {@code email}'s domain belongs to a known disposable-email provider. */
53	    static boolean isDisposable(String email) {
54	        return DISPOSABLE_DOMAINS.contains(domainOf(email));
55	    }
56	}
