1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
5	import static org.junit.jupiter.api.Assertions.assertTrue;
6	import tools.jackson.databind.JsonNode;
7	import tools.jackson.databind.node.ObjectNode;
8	
9	/** identity-key-v2: identityKey = SHA-256 hex over (normalizedTelephone | lowerEmail |
10	 * soundex(lastName)); duplicate detection (409) uses it. The exact key depends on soundex, so the
11	 * deterministic oracle is the collision (identical identity -> 409) plus the exact 64-hex shape. */
12	class AcceptanceTest extends AcceptanceBase {
13	
14		@Test
15		void coreIdentityKeyIsSha256Hex() throws Exception {
16			JsonNode r = fetchOwner(createOwnerOk(structuredOwner()));
17			String key = r.get("identityKey").asText();
18			assertTrue(key.matches("[0-9a-f]{64}"), key);
19		}
20	
21		@Test
22		void coreRejectsDuplicateIdentity() throws Exception {
23			ObjectNode a = structuredOwner();
24			a.put("email", uniqueEmail());
25			createOwnerOk(a);
26			ObjectNode b = a.deepCopy(); // identical telephone / email / lastName -> same v2 key
27			createOwner(b).andExpect(status().isConflict());
28		}
29	}
