67	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
68	    default String initials(Owner owner) {
69	        return initial(owner.getFirstName()) + initial(owner.getLastName());
70	    }
71	
72	    /** The stored E.164 telephone formatted for humans (see {@link OwnerTelephones#toDisplay}). */
73	    default String telephoneDisplay(Owner owner) {
74	        return OwnerTelephones.toDisplay(owner.getTelephone());
75	    }
76	
77	    private static String initial(String name) {
78	        return Character.toUpperCase(name.charAt(0)) + ".";
79	    }
80	
81	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
82	     * last two digits of the fiscal year of the registrationDate (see {@link FiscalYear}). */
83	    default String membershipNumber(Owner owner) {
84	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
85	            return null;
86	        }
87	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
88	    }
89	
90	    /** The owner's 'FY&lt;YY&gt;' fiscal year, derived from the business-day-adjusted
91	     * registrationDate (see {@link FiscalYear}), or null when the date is unknown. */
92	    default String fiscalYear(Owner owner) {
93	        return FiscalYear.label(owner.getRegistrationDate());
94	    }
95	
96	    /** The owner's membership points: starts at 0, plus 2 when an email is present, plus 1 when
97	     * namesakeCount is 0, plus 2 for a household of 3 or more, plus 3 when tenure is at least one
98	     * elapsed fiscal year. */
99	    default int membershipPoints(Owner owner) {
100	        int points = 0;
101	        if (hasEmail(owner)) {
102	            points += 2;
103	        }
104	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
105	            points += 1;
106	        }
107	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
108	            points += 2;
109	        }
110	        if (Tenure.fiscalYears(owner.getRegistrationDate()) >= 1) {
111	            points += 3;
112	        }
113	        return points;
114	    }
115	
116	    /** The owner's membership level from 1 to 4, derived from {@link #membershipPoints(Owner)}:
117	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. When the owner carries a
118	     * {@code membershipLevelCap} (set at creation from their household; see
119	     * {@code AssignOwnerMembershipLevelCap}) the derived level is clamped to that ceiling. */
120	    default int membershipLevel(Owner owner) {
121	        int points = membershipPoints(owner);
122	        int level;
123	        if (points <= 1) {
124	            level = 1;
125	        } else if (points <= 3) {
126	            level = 2;
127	        } else if (points <= 5) {
128	            level = 3;
129	        } else {
130	            level = 4;
131	        }
132	        Integer cap = owner.getMembershipLevelCap();
133	        return cap == null ? level : Math.min(level, cap);
134	    }
135	
136	    /** The owner's canonical region: the REGION segment of the customer code (see
137	     * {@link CustomerCode}), or null when the customer code is unset. */
138	    default String locality(Owner owner) {
139	        return CustomerCode.region(owner.getCustomerCode());
140	    }
141	
142	    /** The owner's IANA timezone, derived from the locality/region via the pinned
143	     * region-to-timezone table (see {@link Locality#timezoneForRegion}), or null when the
144	     * region is not in the table. */
145	    default String timezone(Owner owner) {
146	        return Locality.timezoneForRegion(locality(owner));
147	    }
148	
149	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
150	    default String contactPreference(Owner owner) {
151	        return hasEmail(owner) ? "EMAIL" : "PHONE";
152	    }
153	
154	    /** Whether the owner has a non-blank email. */
155	    private static boolean hasEmail(Owner owner) {
156	        return owner.getEmail() != null && !owner.getEmail().isBlank();
157	    }
158	
159	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
160	    default String identityKey(Owner owner) {
161	        return OwnerIdentity.of(owner);
162	    }
163	
164	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
165	    default Integer checkDigit(Owner owner) {
166	        return owner.getCustomerCode() == null ? null : CheckDigit.luhn(owner.getCustomerCode());
167	    }
168	
169	    /** The owner's age band on their registration date, derived from their birth date (see
170	     * {@link AgeBand}), or null when either date is unset. */
171	    default String ageBand(Owner owner) {
172	        return AgeBand.on(owner.getBirthDate(), owner.getRegistrationDate());
173	    }
174	
175	    /** Whether the owner soft-matched an existing owner at creation, i.e. it has a
176	     * {@code possibleDuplicateOf} id. */
177	    default boolean possibleDuplicate(Owner owner) {
178	        return owner.getPossibleDuplicateOf() != null;
179	    }
180	
181	    @Mapping(target = "id", ignore = true)
182	    @Mapping(target = "pets", ignore = true)
183	    @Mapping(target = "customerCode", ignore = true)
184	    @Mapping(target = "householdId", ignore = true)
185	    @Mapping(target = "namesakeCount", ignore = true)
186	    @Mapping(target = "householdSize", ignore = true)
187	    @Mapping(target = "bulkSignupWarning", ignore = true)
188	    @Mapping(target = "possibleDuplicateOf", ignore = true)
189	    @Mapping(target = "membershipLevelCap", ignore = true)
190	    @Mapping(target = "deleted", ignore = true)
191	    Owner toOwner(OwnerFieldsDto ownerDto);
192	
193	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
194	
195	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
196	
197	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
198	        OwnerPageDto ownerPageDto = new OwnerPageDto();
199	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
200	        ownerPageDto.setPage(ownerPage.getNumber());
201	        ownerPageDto.setSize(ownerPage.getSize());
202	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
203	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
204	        return ownerPageDto;
205	    }
206	}
